type Payment =
  | { readonly kind: "card"; readonly number: string }
  | { readonly kind: "transfer"; readonly iban: string };
const assertNever = (x: never): never => { throw new Error(`unhandled ${JSON.stringify(x)}`); };

function describe(p: Payment): string {
  switch (p.kind) {
    case "card":     return p.number;
    case "transfer": return p.iban;
    default:         return assertNever(p);   // compile error on a new case
  }
}
